    available_mb: number;
    /** Half the CPUs (the browser needs the rest), at least 1. */
    by_cpu: number;
    /** Available RAM / per-slot memory; null when RAM could not be read. */
    by_ram: number | null;
    /** Logical CPUs. */
    cpus: number;
